const init=$('Init').first().json;
const meta=$('Get File Meta').first().json;
const st=$getWorkflowStaticData('global');
const qn=($('Read Quick Numbers').first().json.values)||[];
const ov=($('Read Overview').first().json.values)||[];
const pdfB64=$json.pdfB64||null;

const money=v=>(typeof v==='number')?'$'+v.toLocaleString('en-US',{maximumFractionDigits:0}):'—';
const num  =v=>(typeof v==='number')?v.toLocaleString('en-US',{maximumFractionDigits:0}):'—';
const esc  =s=>String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

const qnRows=qn.slice(4).filter(r=>String(r[0]||'').trim());
let qnHtml='<table cellpadding="8" cellspacing="0" style="border-collapse:collapse;font:14px Segoe UI,Arial,sans-serif;width:100%">'
 +'<tr style="background:#1F3864;color:#fff"><th align="left">Period</th><th align="right">Revenue</th><th align="right">Cases</th><th align="left">What’s included</th></tr>';
qnRows.forEach((r,i)=>{ qnHtml+='<tr style="background:'+(i%2?'#F2F5FA':'#fff')+';border-bottom:1px solid #dde3ec">'
 +'<td><b>'+esc(r[0])+'</b></td><td align="right">'+money(r[1])+'</td><td align="right">'+num(r[2])+'</td>'
 +'<td style="color:#556;font-size:12px">'+esc(r[3])+'</td></tr>'; });
qnHtml+='</table>';

const MN=['','Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const monthRows=ov.slice(1).filter(r=>typeof r[7]==='number');
let ovHtml='<table cellpadding="7" cellspacing="0" style="border-collapse:collapse;font:13px Segoe UI,Arial,sans-serif;width:100%">'
 +'<tr style="background:#1F3864;color:#fff"><th align="left">Month</th><th align="right">Invoiced</th><th align="right">Booked</th>'
 +'<th align="right">Total</th><th align="right">Inv Cases</th><th align="right">Bkd Cases</th></tr>';
let tI=0,tB=0,tIC=0,tBC=0,shown=0;
monthRows.forEach(r=>{ if(!r[1]&&!r[2]) return;
 tI+=r[1]||0;tB+=r[2]||0;tIC+=r[4]||0;tBC+=r[5]||0;
 ovHtml+='<tr style="background:'+(shown++%2?'#F2F5FA':'#fff')+';border-bottom:1px solid #dde3ec"><td><b>'+MN[r[7]]+'</b></td>'
 +'<td align="right">'+money(r[1])+'</td><td align="right">'+money(r[2])+'</td><td align="right">'+money((r[1]||0)+(r[2]||0))+'</td>'
 +'<td align="right">'+num(r[4])+'</td><td align="right">'+num(r[5])+'</td></tr>'; });
ovHtml+='<tr style="background:#E8EDF5;font-weight:bold"><td>Total</td><td align="right">'+money(tI)+'</td><td align="right">'+money(tB)
 +'</td><td align="right">'+money(tI+tB)+'</td><td align="right">'+num(tIC)+'</td><td align="right">'+num(tBC)+'</td></tr></table>';

const find=re=>qnRows.find(r=>re.test(String(r[0])))||[];
const today=find(/^today/i), wtd=find(/week/i), mtd=find(/month to date/i),
      rest=find(/rest of/i), next7=find(/next 7/i);

const imgs=st.img||{};
const atts=[];
if(pdfB64) atts.push({'@odata.type':'#microsoft.graph.fileAttachment',
  name:init.pdfName,contentType:'application/pdf',contentBytes:pdfB64});
[['chart1',imgs.c1],['chart2',imgs.c2],['chart3',imgs.c3]].forEach(([cid,b64])=>{
  if(b64) atts.push({'@odata.type':'#microsoft.graph.fileAttachment',name:cid+'.png',
    contentType:'image/png',contentBytes:b64,isInline:true,contentId:cid});
});
const blk=(cid,key,title)=> imgs[key]
 ? '<h3 style="font:600 15px Segoe UI,Arial;color:#1F3864;margin:26px 0 8px">'+title+'</h3>'
   +'<img src="cid:'+cid+'" style="max-width:100%;border:1px solid #dde3ec;border-radius:4px">':'';


const d=new Date();
const nice=d.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'});

const html='<div style="font:14px Segoe UI,Arial,sans-serif;color:#222;max-width:980px">'
+'<h2 style="color:#1F3864;margin:0 0 4px">RT 21 — Daily Orders &amp; Invoices</h2>'
+'<div style="color:#667;font-size:13px;margin-bottom:18px">'+nice+' &nbsp;·&nbsp; workbook last refreshed '+esc(meta.lastModifiedDateTime||'')+'</div>'
+'<p style="margin:0 0 18px"><a href="'+esc(meta.webUrl)+'" style="color:#1F3864;font-size:15px"><b>Open the live workbook</b></a> <span style="color:#667;font-size:13px">— always current, refreshed each morning from Business Central.</span></p>'
+'<div style="background:#F2F5FA;border-left:4px solid #1F3864;padding:14px 16px;margin-bottom:22px">'
+'<b>Summary.</b> Today is running <b>'+money(today[1])+'</b> across <b>'+num(today[2])+'</b> cases. '
+'Week to date stands at <b>'+money(wtd[1])+'</b> ('+num(wtd[2])+' cases) and month to date at <b>'+money(mtd[1])+'</b> ('+num(mtd[2])+' cases). '
+'A further <b>'+money(rest[1])+'</b> is already booked for the rest of the month, with <b>'+money(next7[1])+'</b> due over the next 7 days. '
+'Year to date the route has invoiced <b>'+money(tI)+'</b> on '+num(tIC)+' cases, and carries <b>'+money(tB)+'</b> of open orders.'
+'</div>'
+'<h3 style="font:600 15px Segoe UI,Arial;color:#1F3864;margin:0 0 8px">Quick Numbers</h3>'+qnHtml
+'<h3 style="font:600 15px Segoe UI,Arial;color:#1F3864;margin:26px 0 8px">Monthly — Invoiced vs Booked</h3>'+ovHtml
+blk('chart1','c1','Revenue by Month (Invoiced + Booked)')
+blk('chart2','c2','Cases by Month (Invoiced + Booked)')
+blk('chart3','c3','Revenue by State — Selected vs Comparison Month')
+'<p style="margin:0 0 18px;color:#556">'+(pdfB64?'Attached is a static PDF of the report sheets as they stood this morning — a fixed point‑in‑time record that will not move under you.':'<i>PDF attachment unavailable for this run.</i>')+'</p>'
+'</div>';

