  delUrl: 'https://graph.microsoft.com/v1.0/drives/b!GBMH8cf5mk2CZl1ZfpWgDMJRDzREsg1Npw0_haVaoSy_p0-rU6CqTIb8wOlQB4p-'+'/items/'+st.snapId,
